export const STYLE_QUESTIONS = {"general":[{"text":"What are the primary goals and objectives of the system?","src":"Arch Style Suitability Ass!B9"},{"text":"What are the key functional and non-functional requirements?","src":"Arch Style Suitability Ass!B10"},{"text":"What are the critical quality attributes for the system (e.g., performance, scalability, security, maintainability)?","src":"Arch Style Suitability Ass!B11"}],"decide":[{"text":"Which architectural style best aligns with the system's goals, requirements, and quality attributes?","src":"Arch Style Suitability Ass!B55"},{"text":"What are the trade-offs of each architectural style in the context of the system?","src":"Arch Style Suitability Ass!B56"},{"text":"Which architectural style best fits the team's structure and expertise?","src":"Arch Style Suitability Ass!B57"},{"text":"What are the risks and challenges associated with each architectural style?","src":"Arch Style Suitability Ass!B58"}]};
export const PATTERNS = [{"id":"P-CHECK-POINTED-SYSTEM","name":"Check-pointed System","effects":{"availability":"x"},"also":{},"text":"This pattern improves availability by creating checkpoints or snapshots of the system's state, allowing for rollback and recovery in case of failures.","example":"In a database system, regular backups can act as checkpoints, enabling restoration to a previous consistent state if a failure occurs.","catalogue":"Backup and Restore","src":"Table Analysis_Architectural Patterns and Quality Properties.docx (line 7); Arch PAttern + Quality Prop.!B5:B36"},{"id":"P-STANDBY","name":"Standby","effects":{"availability":"x"},"also":{},"text":"This pattern involves having a redundant standby component or system that can take over in case the primary component fails.","example":"In a web application, a load balancer can distribute traffic between multiple server instances, and if one instance fails, the load balancer automatically redirects traffic to the standby instance.","catalogue":"Active-Passive","src":"Table Analysis_Architectural Patterns and Quality Properties.docx (line 11); Arch PAttern + Quality Prop.!B5:B36"},{"id":"P-COMPARATOR-CHECKED-FAULT-TOLERANT","name":"Comparator-Checked Fault Tolerant","effects":{"availability":"x"},"also":{"Safety":"x"},"text":"This pattern enhances availability by using multiple components that perform the same task and comparing their results to detect and recover from errors.","example":"In a flight control system, multiple computers might perform the same calculations, and their outputs are compared to ensure consistency and detect potential errors.","catalogue":null,"src":"Table Analysis_Architectural Patterns and Quality Properties.docx (line 15); Arch PAttern + Quality Prop.!B5:B36"},{"id":"P-PROTECTED-SYSTEM","name":"Protected System","effects":{"availability":"x","security":"x"},"also":{"Safety":"x"},"text":"This pattern improves availability by isolating critical components or subsystems from potential failures or external threats.","example":"In a critical infrastructure system, a protected system might be implemented using a separate, secure network and dedicated hardware to isolate it from potential cyberattacks or failures in other parts of the network.","catalogue":null,"src":"Table Analysis_Architectural Patterns and Quality Properties.docx (line 19); Arch PAttern + Quality Prop.!B5:B36"},{"id":"P-SECURE-COMMUNICATION","name":"Secure Communication","effects":{"availability":"x","security":"x"},"also":{"Safety":"x"},"text":"This pattern enhances availability by ensuring secure and reliable communication between components, preventing disruptions caused by communication failures or security breaches.","example":"Using encryption and authentication protocols for communication between microservices can improve the system's resilience to communication failures and security attacks.","catalogue":"Data Encryption in Transit","src":"Table Analysis_Architectural Patterns and Quality Properties.docx (line 23); Arch PAttern + Quality Prop.!B5:B36"},{"id":"P-CANARY-DEPLOYMENT","name":"Canary Deployment","effects":{"deployability":"x"},"also":{"Migration between versions":"x"},"text":"This pattern supports deployability by enabling gradual rollout of new versions or features to a subset of users, allowing for controlled testing and minimizing the impact of potential issues.","example":"A new version of a website might be deployed to a small percentage of users initially, and if no issues are observed, the rollout can be gradually expanded to the rest of the users.","catalogue":"Canary Release","src":"Table Analysis_Architectural Patterns and Quality Properties.docx (line 29); Arch PAttern + Quality Prop.!B5:B36"},{"id":"P-FACADE","name":"Facade","effects":{"maintainability":"(x)","performance":"(x)"},"also":{"Encapsulation of common-case behaviour":"x","Migration between versions":"x"},"text":"This pattern provides a simplified interface to a complex subsystem, hiding the internal complexity and making it easier to use. This encapsulation can improve maintainability and reduce the impact of changes within the subsystem.","example":"In a complex e-commerce system, a Facade pattern can provide a unified interface for modules like product catalog, order management, and payment processing, simplifying interactions for other components or external systems.","catalogue":"Facade","src":"Table Analysis_Architectural Patterns and Quality Properties.docx (line 35); Arch PAttern + Quality Prop.!B5:B36"},{"id":"P-MEDIATOR","name":"Mediator","effects":{"maintainability":"x","scalability":"(x)"},"also":{},"text":"This pattern centralizes communication between components, reducing dependencies and making the system easier to understand and modify.","example":"In a system with many interconnected components, a Mediator pattern can manage the communication between them, reducing the number of direct dependencies and making it easier to add, remove, or modify components without affecting the entire system.","catalogue":null,"src":"Table Analysis_Architectural Patterns and Quality Properties.docx (line 43); Arch PAttern + Quality Prop.!B5:B36"},{"id":"P-ADAPTER","name":"Adapter","effects":{},"also":{"Migration between versions":"x","Reusability":"x"},"text":"This pattern allows for integrating components with different interfaces, which can be useful during system migration when new components need to interact with legacy components.","example":"During a database migration, an adapter can be used to allow a new application to interact with the old database schema while the data is being migrated to the new schema.","catalogue":"Adapter","src":"Table Analysis_Architectural Patterns and Quality Properties.docx (line 49); Arch PAttern + Quality Prop.!B5:B36"},{"id":"P-STRANGLER","name":"Strangler","effects":{},"also":{"Migration between versions":"x"},"text":"This pattern enables gradual migration by replacing parts of the system incrementally, allowing for a phased transition and reducing the risk of disruption.","example":"A legacy e-commerce system can be gradually migrated to a new platform by implementing new features as microservices and using the Strangler pattern to redirect traffic from the old system to the new services incrementally.","catalogue":"Strangler Fig","src":"Table Analysis_Architectural Patterns and Quality Properties.docx (line 57); Arch PAttern + Quality Prop.!B5:B36"},{"id":"P-OBSERVER","name":"Observer","effects":{"maintainability":"x","performance":"(x)"},"also":{"Responsiveness":"x"},"text":"This pattern enables flexible event-based communication, allowing components to be easily added or removed without affecting the overall system behavior.","example":"In a system with real-time notifications, new notification channels (e.g., SMS, push notifications) can be added without modifying the core notification logic.","catalogue":"Publish-Subscribe","src":"Table Analysis_Architectural Patterns and Quality Properties.docx (line 67); Arch PAttern + Quality Prop.!B5:B36"},{"id":"P-STRATEGY","name":"Strategy","effects":{"maintainability":"x"},"also":{"Portability":"(x)"},"text":"This pattern allows for interchangeable algorithms or strategies, making it easy to modify or extend the system's behavior.","example":"In a machine learning system, different algorithms can be implemented as strategies and easily swapped or added without affecting the rest of the system.","catalogue":"Strategy Pattern","src":"Table Analysis_Architectural Patterns and Quality Properties.docx (line 71); Arch PAttern + Quality Prop.!B5:B36"},{"id":"P-THROTTLING","name":"Throttling","effects":{"maintainability":"x","performance":"(x)","scalability":"(x)"},"also":{},"text":"This pattern enables dynamic adjustment of resource usage, which can be useful for adapting to changing workloads or preventing overload.","example":"In a cloud-based application, throttling can be used to limit the rate of requests to a service, preventing it from being overwhelmed during peak traffic.","catalogue":"Throttling","src":"Table Analysis_Architectural Patterns and Quality Properties.docx (line 75); Arch PAttern + Quality Prop.!B5:B36"},{"id":"P-CONTROLLER-RESPONDER","name":"Controller-responder","effects":{"performance":"(x)"},"also":{},"text":"This pattern can optimize resource allocation and improve performance by efficiently managing the assignment of tasks to components.","example":"In a distributed system, a controller-responder pattern can be used to assign tasks to worker nodes based on their availability and capacity, optimizing resource utilization and improving overall performance.","catalogue":null,"src":"Table Analysis_Architectural Patterns and Quality Properties.docx (line 83); Arch PAttern + Quality Prop.!B5:B36"}];
