export const ANTI_PATTERNS = [{"id":"AP-TIGHT-COUPLING","name":"Tight Coupling","text":"Tight coupling between services can make it difficult to modify or update individual services without affecting others. This can be mitigated by using techniques like dependency injection and well-defined interfaces.","catalogue":"Distributed Monolith","src":"anti patterns!B41"},{"id":"AP-GOD-SERVICE","name":"God Services","text":"Services that have too many responsibilities or handle unrelated functionalities can become complex and difficult to maintain. This can be addressed by decomposing large services into smaller, more focused ones.","catalogue":"God Service","src":"anti patterns!B42"},{"id":"AP-DUPLICATED-CODE","name":"Duplicated Code","text":"Duplicated code across services can lead to inconsistencies and increase maintenance effort. This can be mitigated by refactoring common functionalities into reusable components or libraries.","catalogue":"Copy-Paste Architecture","src":"anti patterns!B43"},{"id":"AP-NO-DOCS","name":"Lack of Documentation","text":"Poor or missing documentation can make it difficult to understand the architecture and its components, hindering maintainability and evolution. This can be addressed by prioritizing documentation and using tools to generate and maintain up-to-date documentation.","catalogue":null,"src":"anti patterns!B44"}];
export const DECISION_TEMPLATE = {"fields":["Decision ID","Decision Name","Decision Description","Rationale","Assumptions and Risks","Scaling","Trade-offs"],"src":"Sheet45!B9:H9","examples":[{"id":"D.05","name":"Adoption of Microservices Architecture Style","src":"Sheet45!B10:H10"},{"id":"D.06","name":"Adoption of Event-Driven Architecture Style","src":"Sheet45!B16:H16"}]};

const byId = new Map([...ATTRIBUTES, ...TACTICS, ...STYLES, ...PATTERNS, ...ANTI_PATTERNS].map(x => [x.id, x]));
export const knowledge = id => byId.get(id) || null;
export const attribute = id => ATTRIBUTES.find(a => a.id === id) || null;
export const family = id => FAMILIES.find(f => f.id === id) || null;
export const tacticsFor = id => TACTICS.filter(t => t.attribute === id);
export const patternsFor = id => PATTERNS.filter(p => p.effects[id]);
export const stylesFor = id => STYLES.filter(s => s.effects[id]);
export const MARK = {'x': 'strong support', '(x)': 'conditional support'};
// Where a playbook entry comes from, in words a reader can follow back to the file.
export function locator(src) {
  const s = String(src || '');
  return s.includes('.docx') ? s.replace(/\.docx/, '') : s.replace(/^([^!]+)!/, 'SA Playbook › $1 › ');
}
